def factorial(n):
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

function reverseString(str) {
    let reversed = '';
    for (let i = str.length - 1; i >= 0; i--) {
        reversed += str[i];
    }
    return reversed;
}

def find_max(lst):
    if not lst:
        return None
    max_val = lst[0]
    for val in lst:
        if val > max_val:
            max_val = val
    return max_val

function isPrime(num) {
    if (num <= 1) return false;
    for (let i = 2; i <= Math.sqrt(num); i++) {
        if (num % i === 0) return false;
    }
    return true;
}

def fibonacci_iterative(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def merge_dicts(d1, d2):
    merged = d1.copy()
    for k, v in d2.items():
        merged[k] = merged.get(k, 0) + v
    return merged

def remove_duplicates(lst):
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

function isAnagram(str1, str2) {
    const format = str => str.toLowerCase().replace(/[^a-z0-9]/g, '').split('').sort().join('');
    return format(str1) === format(str2);
}

def bubble_sort(lst):
    n = len(lst)
    for i in range(n):
        for j in range(0, n - i - 1):
            if lst[j] > lst[j + 1]:
                lst[j], lst[j + 1] = lst[j + 1], lst[j]
    return lst

def binary_search(lst, target):
    low, high = 0, len(lst) - 1
    while low <= high:
        mid = (low + high) // 2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

function checkBalancedParentheses(str) {
    let count = 0;
    for (let char of str) {
        if (char === '(') count++;
        else if (char === ')') count--;
        if (count < 0) return false;
    }
    return count === 0;
}

def count_vowels(s):
    vowels = 'aeiouAEIOU'
    counts = {v: 0 for v in 'aeiou'}
    for char in s:
        if char.lower() in counts:
            counts[char.lower()] += 1
    return counts

